message.content:
{
  "connections": [
    {
      "event": "Q184928",
      "type": "shaped_by",
      "reason": "The 1905 Russian Revolution inspired Luxemburg to formulate her theory of the mass strike as an essential revolutionary tool.",
      "evidence": "Inspired by the 1905 Russian Revolution, she developed a theory of the mass strike as the proletariat's most important revolutionary tool, emphasizing the spontaneous creativity of the working class.",
      "work": ""
    },
    {
      "event": "Q361",
      "type": "wrote_in_response_to",
      "reason": "Luxemburg wrote the Junius Pamphlet while imprisoned to denounce World War I as a betrayal of the working class.",
      "evidence": "From prison, she wrote the influential Junius Pamphlet, which declared the war a betrayal of the working class and popularized the phrase \"socialism or barbarism\" to describe the choice facing humanity.",
      "work": "Junius Pamphlet"
    },
    {
      "event": "Q8729",
      "type": "wrote_in_response_to",
      "reason": "Luxemburg addressed the 1917 Russian Revolution in a manuscript that critiqued the authoritarian policies of the Bolsheviks.",
      "evidence": "While she celebrated the Russian Revolution of 1917, in a posthumously published manuscript she offered a sharp critique of the Bolsheviks' authoritarian policies, defending democratic freedoms and the need for a revolution rooted in mass participation.",
      "work": ""
    },
    {
      "event": "Q170306",
      "type": "took_part_in",
      "reason": "Luxemburg took an active leadership role during the German Revolution of 1918–1919 by co-founding the KPD and participating in the Spartacist uprising.",
      "evidence": "Released from prison during the German Revolution of 1918–1919, Luxemburg co-founded the KPD and became a central figure in the January 1919 Spartacist uprising in Berlin.",
      "work": ""
    },
    {
      "event": "Q107649202",
      "type": "suffered_under",
      "reason": "Following the suppression of the Spartacist uprising, Luxemburg and Karl Liebknecht were captured and murdered by the Freikorps.",
      "evidence": "After the uprising was crushed by the Freikorps, a government-sponsored paramilitary group, Luxemburg and her comrade Karl Liebknecht were captured and killed.",
      "work": ""
    }
  ]
}

